CREATE POLICY "Users can upload their cake refs" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'cake-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can read their cake refs" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'cake-references' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can delete their cake refs" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'cake-references' AND (storage.foldername(name))[1] = auth.uid()::text);